package com.jnapanam.sportszone.identity.service;
import com.jnapanam.sportszone.identity.model.*;import com.jnapanam.sportszone.identity.repository.*;import java.util.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.boot.ApplicationArguments;import org.springframework.boot.ApplicationRunner;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.stereotype.Component;import org.springframework.transaction.annotation.Transactional;
@Component public class SuperAdminBootstrap implements ApplicationRunner{
 private final UserRepository users;private final RoleRepository roles;private final PasswordEncoder passwords;private final String email;private final String password;private final String name;
 public SuperAdminBootstrap(UserRepository users,RoleRepository roles,PasswordEncoder passwords,@Value("${app.bootstrap.super-admin-email:}")String email,@Value("${app.bootstrap.super-admin-password:}")String password,@Value("${app.bootstrap.super-admin-name:Jnapanam Super Admin}")String name){this.users=users;this.roles=roles;this.passwords=passwords;this.email=email;this.password=password;this.name=name;}
 @Override@Transactional public void run(ApplicationArguments args){if(users.countByRole(RoleName.SUPER_ADMIN)>0||email.isBlank()||password.isBlank())return;if(password.length()<12)throw new IllegalStateException("BOOTSTRAP_SUPER_ADMIN_PASSWORD must contain at least 12 characters");Role customer=roles.findByName(RoleName.CUSTOMER).orElseThrow();Role superAdmin=roles.findByName(RoleName.SUPER_ADMIN).orElseThrow();User user=users.findByEmailIgnoreCase(email).orElseGet(()->users.save(new User(name,email.trim().toLowerCase(Locale.ROOT),null,passwords.encode(password),customer)));user.replaceRoles(Set.of(superAdmin));user.password(passwords.encode(password),true);}
}
